"use strict";
// A bundler's lazy module object holding an ES5 constructor: the checker
// cannot type the object, so the constructor is an untyped value where
// `instanceof` tests it.
var types = {};
var hasTypes;
function requireTypes() {
  if (hasTypes) return types;
  hasTypes = 1;
  function Type(tag, options) {
    this.tag = tag;
    this.kind = (options && options.kind) || "scalar";
  }
  function Schema(list) {
    this.list = list;
  }
  types.Type = Type;
  types.Schema = Schema;
  types.make = (tag) => new Type(tag);
  return types;
}
var loaded = requireTypes();
var Type = loaded.Type;
var Schema = loaded.Schema;
var make = loaded.make;

function compileList(list) {
  var tags = [];
  list.forEach(function (item) {
    if (!(item instanceof Type)) throw new Error("not a Type: " + JSON.stringify(item));
    tags.push(item.tag + ":" + item.kind);
  });
  return tags;
}
// Runs when the module loads, as js-yaml's default schema does.
var defaults = new Schema(compileList([new Type("!str"), new Type("!seq", { kind: "sequence" })]));

module.exports.describe = function (json) {
  var value = JSON.parse(json);
  return [value instanceof Type, value instanceof Schema, defaults instanceof Schema, defaults instanceof Type].join(",");
};
module.exports.tags = function () {
  return defaults.list.join(" ");
};
function rejects(json) {
  try {
    compileList([JSON.parse(json)]);
    return "accepted";
  } catch (error) {
    return error.message;
  }
}
module.exports.rejects = rejects;
// An arrow function has no prototype: Node throws a TypeError for an object.
module.exports.arrowCheck = function (json) {
  try {
    return String(JSON.parse(json) instanceof make);
  } catch (error) {
    return error.name + ": " + error.message;
  }
};
// Every object reaches the TypeError, typed arrays, promises and Maps too.
module.exports.arrowObjects = function () {
  return [new Uint8Array(2), Promise.resolve(1), new Map(), [1]].map(function (value) {
    try {
      return String(value instanceof make);
    } catch (error) {
      return error.name;
    }
  }).join(",");
};
